                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SUNBEAM_DB.MAPLEMONK.SUNBEAM_MYNTRA_ORDERS_FACT_ITEMS AS SELECT * FROM ( SELECT \'MYNTRA PPMP\' AS SHOP_NAME, \'MYNTRA PPMP\' AS MARKETPLACE, \'MYNTRA PPMP\' AS CHANNEL, \'MYNTRA PPMP\' AS SOURCE, CAST(\"order id fk\" AS VARCHAR) AS ORDER_ID_FK, CAST(\"seller order id\" AS VARCHAR) AS ORDER_ID, CAST(\"store order id\" AS VARCHAR) AS STORE_ORDER_ID, CAST(\"order line id\" AS NUMBER(38,0)) AS ORDER_LINE_ID, CAST(\"order tracking number\" AS VARCHAR) AS ORDER_TRACKING_NUMBER, CAST(\"sku id\" AS VARCHAR) AS SKU_ID, CAST(\"myntra sku code\" AS VARCHAR) AS MYNTRA_SKU_CODE, CAST(\"seller sku code\" AS VARCHAR) AS SELLER_SKU_CODE, CAST(\"style id\" AS NUMBER(38,0)) AS STYLE_ID, CAST(pp.size AS VARCHAR) AS SIZE, UPPER(CAST(\"style name\" AS VARCHAR)) AS PRODUCT_NAME, CAST(pp.brand AS VARCHAR) AS BRAND, CAST(\"vendor article number\" AS VARCHAR) AS SKU, CAST(\"article type\" AS VARCHAR) AS PRODUCT_CATEGORY, CAST(state AS VARCHAR) AS STATE, CAST(city AS VARCHAR) AS CITY, CAST(zipcode AS VARCHAR) AS ZIPCODE, CAST(\"warehouse id\" AS NUMBER(38,0)) AS WAREHOUSE_ID, CAST(\"seller warehouse id\" AS NUMBER(38,0)) AS SELLER_WAREHOUSE_ID, CAST(\"courier code\" AS VARCHAR) AS COURIER_CODE, CASE WHEN \"created on\" IS NULL OR TRIM(\"created on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"created on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS CREATED_DATE, CASE WHEN \"packed on\" IS NULL OR TRIM(\"packed on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"packed on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS PACKED_DATE, CASE WHEN \"inscanned on\" IS NULL OR TRIM(\"inscanned on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"inscanned on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS INSCANNED_DATE, CASE WHEN \"shipped on\" IS NULL OR TRIM(\"shipped on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"shipped on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS SHIPPED_DATE, CASE WHEN \"delivered on\" IS NULL OR TRIM(\"delivered on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"delivered on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS DELIVERED_DATE, CASE WHEN \"cancelled on\" IS NULL OR TRIM(\"cancelled on\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"cancelled on\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS CANCELLED_DATE, CASE WHEN \"rto creation date\" IS NULL OR TRIM(\"rto creation date\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"rto creation date\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS RTO_CREATION_DATE, CASE WHEN \"return creation date\" IS NULL OR TRIM(\"return creation date\") = \'\' THEN NULL ELSE TO_DATE(TRY_TO_TIMESTAMP_NTZ(SUBSTR(\"return creation date\", 1, 19), \'YYYY-MM-DD HH24:MI:SS\')) END AS RETURN_CREATION_DATE, TRY_TO_DOUBLE(\"total mrp\") AS TOTAL_MRP, TRY_TO_DOUBLE(\"seller price\") AS SELLER_PRICE, TRY_TO_DOUBLE(\"final amount\") AS SELLING_PRICE, CAST(1 AS NUMBER(38,0)) AS QUANTITY, TRY_TO_DOUBLE(discount) AS DISCOUNT, TRY_TO_DOUBLE(\"coupon discount\") AS COUPON_DISCOUNT, TRY_TO_DOUBLE(\"tax recovery\") AS TAX_RECOVERY, TRY_TO_DOUBLE(\"shipping charge\") AS SHIPPING_CHARGE, TRY_TO_DOUBLE(\"gift charge\") AS GIFT_CHARGE, TRY_TO_DOUBLE( NULLIF(REPLACE(TRIM(\"gt charges\"), \'NA\', \'\'), \'\') ) AS GT_CHARGES, CAST(\"cancellation reason\" AS VARCHAR) AS CANCELLATION_REASON, CASE WHEN UPPER(\"order status\") = \'C\' THEN \'DELIVERED\' WHEN UPPER(\"order status\") = \'F\' THEN \'CANCELLED\' WHEN UPPER(\"order status\") = \'L\' THEN \'LOST\' WHEN UPPER(\"order status\") = \'PK\' THEN \'PACKED\' WHEN UPPER(\"order status\") = \'SH\' THEN \'SHIPPED\' WHEN UPPER(\"order status\") = \'RTO\' THEN \'RTO\' WHEN UPPER(\"order status\") = \'WP\' THEN \'OTHERS\' END AS ORDER_STATUS, CAST(\"order release id\" AS VARCHAR) AS ORDER_RELEASE_ID, NULL AS COMMONSKU, UPPER(CAST(\"style name\" AS VARCHAR)) AS PRODUCT_NAME_FINAL, ROW_NUMBER() OVER ( PARTITION BY \"order id fk\", \"seller order id\" ORDER BY \"created on\" DESC ) AS RW FROM SUNBEAM_DB.MAPLEMONK.sunbeam_myntra_new_get_seller_orders_report pp ) WHERE RW = 1;",
